<script setup>
import { computed,onMounted,reactive,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { ElMessage,ElMessageBox } from 'element-plus';import http from '../api/http';import { useAuthStore } from '../stores/auth';import { dateText,statusText } from '../utils/format'
const route=useRoute(),router=useRouter(),auth=useAuthStore(),task=ref(null),applications=ref([]),applyVisible=ref(false),applyForm=reactive({message:'',expectedFinishTime:''}),loading=ref(false);const isOwner=computed(()=>auth.user?.id===task.value?.publisherId);const canApply=computed(()=>task.value?.status==='RECRUITING'&&!isOwner.value);async function load(){task.value=await http.get(`/api/public/tasks/${route.params.id}`);if(isOwner.value&&task.value.status==='RECRUITING')await loadApplications()}async function loadApplications(){const data=await http.get(`/api/tasks/${route.params.id}/applications`);applications.value=data.records}async function apply(){if(!auth.loggedIn)return router.push({path:'/login',query:{redirect:route.fullPath}});loading.value=true;try{await http.post(`/api/tasks/${route.params.id}/applications`,applyForm);ElMessage.success('申请已提交');applyVisible.value=false}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}async function accept(id){await ElMessageBox.confirm('确认选择这位同学接取任务？其他申请将自动拒绝。','选择接取者');try{const data=await http.post(`/api/applications/${id}/accept`);ElMessage.success('已建立任务订单');router.push(`/orders/${data.order.id}`)}catch(e){ElMessage.error(e.message)}}async function cancel(){await ElMessageBox.confirm('取消后冻结积分将退回，任务记录仍会保留。','取消任务');try{await http.post(`/api/tasks/${route.params.id}/cancel`);ElMessage.success('任务已取消');load()}catch(e){ElMessage.error(e.message)}}async function abnormal(){const {value}=await ElMessageBox.prompt('请说明异常情况和双方争议点','发起异常处理',{inputType:'textarea',inputValidator:v=>v?.length>3||'请填写说明'});try{await http.post(`/api/tasks/${route.params.id}/abnormal`,{reasonType:'DISPUTE',description:value});ElMessage.success('已进入异常处理');load()}catch(e){ElMessage.error(e.message)}}onMounted(load)
</script>
<template><div v-if="task"><div class="page-head"><div><el-tag effect="plain" type="success">{{task.category}}</el-tag><h1 style="margin-top:12px">{{task.title}}</h1><p>{{task.publisherNickname}} 发布 · 信用 {{task.publisherCredit}}</p></div><span class="status-pill">{{statusText(task.status)}}</span></div><div class="two-col"><section class="surface panel"><h3 class="panel-title">任务说明</h3><p style="white-space:pre-wrap;line-height:1.85">{{task.description}}</p><el-descriptions :column="1" border style="margin-top:24px"><el-descriptions-item label="任务地点">{{task.location||'待沟通'}}</el-descriptions-item><el-descriptions-item label="任务时间">{{dateText(task.taskTime)}}</el-descriptions-item><el-descriptions-item label="申请截止">{{dateText(task.applicationDeadline)}}</el-descriptions-item><el-descriptions-item label="信用要求">不低于 {{task.minCreditScore}} 分</el-descriptions-item></el-descriptions><div class="action-row" style="margin-top:22px"><el-button v-if="canApply" type="primary" size="large" @click="applyVisible=true">申请接取</el-button><el-button v-if="isOwner&&task.status==='RECRUITING'" type="danger" plain @click="cancel">取消任务</el-button><el-button v-if="auth.loggedIn&&['IN_PROGRESS','WAIT_ACCEPTANCE'].includes(task.status)" type="warning" plain @click="abnormal">发起异常处理</el-button></div></section><aside class="section-stack"><section class="surface panel"><span class="muted">任务奖励</span><div class="points" style="font-size:38px;margin:8px 0">{{task.rewardPoints}} <small style="font:14px sans-serif">积分</small></div><p class="muted" style="font-size:13px">发布时已冻结，验收通过后自动结算</p></section><section v-if="isOwner&&task.status==='RECRUITING'" class="surface panel"><h3 class="panel-title">接取申请（{{applications.length}}）</h3><div v-for="item in applications" :key="item.application.id" class="list-card" style="background:#f4f6f2"><strong>{{item.applicant.nickname}}</strong><span class="muted"> · 信用 {{item.applicant.creditScore}}</span><p>{{item.application.message||'未填写申请说明'}}</p><el-button v-if="item.application.status==='PENDING'" size="small" type="primary" @click="accept(item.application.id)">选择 TA</el-button><el-tag v-else size="small">{{statusText(item.application.status)}}</el-tag></div><div v-if="!applications.length" class="muted">还没有同学申请</div></section></aside></div><el-dialog v-model="applyVisible" title="申请接取任务" width="480"><el-form label-position="top"><el-form-item label="申请说明"><el-input v-model="applyForm.message" type="textarea" :rows="4" placeholder="介绍你的经验、可用时间等"/></el-form-item><el-form-item label="预计完成时间"><el-date-picker v-model="applyForm.expectedFinishTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" class="full"/></el-form-item></el-form><template #footer><el-button @click="applyVisible=false">取消</el-button><el-button type="primary" :loading="loading" @click="apply">提交申请</el-button></template></el-dialog></div></template>
